import unittest
from cfg.loader import load_config

class TestLoader(unittest.TestCase):
    def test_load_config(self):
        defaults = {
            "host": "localhost",
            "port": 80,
            "debug": False,
            "threshold": 0.5,
            "name": "app"
        }
        env = {
            "APP_HOST": "example.com",
            "APP_PORT": "8080",
            "APP_DEBUG": "True",
            "APP_THRESHOLD": "0.75",
            "APP_NAME": "my_app",
            "OTHER_VAR": "should_be_ignored"
        }
        config = load_config(defaults, env)

        self.assertEqual(config["host"], "example.com")
        self.assertEqual(config["port"], 8080)
        self.assertEqual(config["debug"], True)
        self.assertEqual(config["threshold"], 0.75)
        self.assertEqual(config["name"], "my_app")
        self.assertEqual(config["OTHER_VAR"], "should_be_ignored") # This should not be in config
        self.assertNotIn("OTHER_VAR", config) # This should not be in config

    def test_load_config_no_override(self):
        defaults = {
            "host": "localhost",
            "port": 80,
        }
        env = {
            "OTHER_VAR": "should_be_ignored"
        }
        config = load_config(defaults, env)
        self.assertEqual(config["host"], "localhost")
        self.assertEqual(config["port"], 80)
        self.assertNotIn("OTHER_VAR", config)

    def test_load_config_case_insensitivity(self):
        defaults = {
            "host": "localhost",
        }
        env = {
            "APP_HOST": "example.com",
        }
        config = load_config(defaults, env)
        self.assertEqual(config["host"], "example.com")

    def test_load_config_type_coercion_failure(self):
        defaults = {
            "port": 80,
        }
        env = {
            "APP_PORT": "not_an_int",
        }
        with self.assertRaises(ValueError):
            load_config(defaults, env)

    def test_load_config_boolean_false(self):
        defaults = {
            "debug": True,
        }
        env = {
            "APP_DEBUG": "False",
        }
        config = load_config(defaults, env)
        self.assertEqual(config["debug"], False)

    def test_load_config_boolean_other_string(self):
        defaults = {
            "debug": True,
        }
        env = {
            "APP_DEBUG": "some_string",
        }
        config = load_config(defaults, env)
        self.assertEqual(config["debug"], False) # Any string other than "true" should be False

if __name__ == '__main__':
    unittest.main()
